    w.del_flag = '0'

        and w.work_order_no like concat('%', #{workOrderNo}, '%')


        and w.customer_org_id = #{customerOrgId}


        and w.device_id = #{deviceId}


        and w.title like concat('%', #{title}, '%')


        and w.priority = #{priority}


        and w.status = #{status}


        and w.assignee_user_id = #{assigneeUserId}


order by field(w.priority, '3', '2', '1', '0'),
         field(w.status, '0', '1', '2', '3'),
         w.create_time desc, w.work_order_id desc

